    local hostageAllowedWeapons = {
        "WEAPON_COMBATPISTOL",
        "WEAPON_REVOLVER_MK2",
        "WEAPON_REVOLVER",
        "WEAPON_PISTOL_MK2",
        "WEAPON_PISTOL50",
